-- LF-05 source-aligned next-six *REVIEW CANDIDATES*. Not a release.
-- Source: exact Founder-provided AQA 7182 v1.4, SHA256 db561ba9c36a9109830bcb03bb16d138b85907f068620cce01eff70fdee6ad4d;
-- and AQA 7132 v2.0 SHA256 3217d9dc75aedcf3be14fb95f3d11d536e0626cf10111bc058d9add8a5fce332.
-- Original stems from PR #834 independently challenged at receipt #14124482254,
-- exact reviewed head 675fdc8c53a224fe8fa9a81079b57b15dafef7af;
-- each had no material findings (PASS/MINOR), but marking guidance
-- has been substantively edited and needs *new* exact-version independent A3/A4.
-- For that reason all six rows are HELD and invisible to learners.
begin;
create temporary table lf05_next_six(
id text,course_id text,paper_number smallint,topic_id text,skill_ref text,title text,
question_prompt text,stimulus text,marks_style smallint,guidance jsonb,
approved_source_ref text,approved_review_ref text) on commit drop;
insert into lf05_next_six values
('PSY-LF05-01','aqa:aqa-a-level:7182',1,'social-influence','AQA 7182 v1.4 §4.1.1 — resistance to social influence','Social support and locus of control','Describe and evaluate the roles of social support and locus of control in explaining why people resist social influence.',NULL,16,'["Training classification: Original Revision 16-mark-style extended-writing practice; no confirmed item-level AQA 2027 mark tariff or examiner-calibrated numeric AO allocation.","Accurate subject knowledge: Explain how social support (including a dissenting ally) can reduce unanimity or obedience pressure, and how internal versus external locus of control relates to perceived personal control. Distinguish conformity and obedience where relevant.","Reasoned evaluation: Weigh controlled evidence about dissenting allies against generalisability and context. Discuss limitations of associations between locus of control and resistance; correlation does not show that perceived control alone causes resistance.","Comparative analysis: Contrast situational social support with dispositional locus of control; neither factor guarantees resistance. Address when each explanation is useful and how context changes its predictions.","Creditworthy alternatives: Relevant social-norm, legitimacy or experience arguments are creditworthy when explicitly connected to the named explanations. No one named classic experiment is mandatory for every valid explanation.","Response quality: Strong answers develop accurate mechanisms, evidence-sensitive limitations and a justified answer-focused judgement. The judgement may be woven through the evaluation; do not require a separate final paragraph.","Self-review prompt: Did I explain both mechanisms, evaluate the evidence rather than simply cite it, and distinguish tendencies from a proven cause of an individual''s behaviour?"]'::jsonb,'PR834 original reviewed head 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7182 v1.4 §4.1.1 — resistance to social influence; new guide A3 pending','historical A3 43620992688 item PSY-LF05-01: no material findings; revised-guide A3/A4 HOLD'),
('PSY-LF05-02','aqa:aqa-a-level:7182',1,'memory','AQA 7182 v1.4 §4.1.2 — working-memory model','Working-memory model and concurrent tasks','Discuss the working-memory model as an explanation of how people may carry out different short-term memory tasks at the same time.',NULL,16,'["Training classification: Original Revision 16-mark-style extended-writing exercise; the precise AQA 2027 item tariff and per-item AO split are not established.","Accurate knowledge: Describe the central executive, phonological loop, visuo-spatial sketchpad and episodic buffer, addressing coding/processing differences and the model''s limited-capacity resources.","Task linkage: Explain why concurrent tasks drawing on different subsystems may interfere less than tasks competing for the same resources; attentional demands, complexity and executive limits can still produce interference.","Evaluation: Use relevant dual-task research and, where accurate, neuropsychological cases as qualified support. Recognise the limitations of laboratory dual-task designs and difficulty specifying the central executive precisely.","Creditworthy alternatives: Relevant cognitive or neural findings are acceptable if their implications are explained. Correct component knowledge earns recognition even when the task link is weak, but it is not by itself a developed discussion.","Response quality: Strong answers connect processes to actual concurrent-task demands, evaluate counterexamples and reach a sustained, qualified judgement about what the model explains and leaves unresolved; a separate formal conclusion is not essential.","Self-review prompt: Did I apply the components to both compatible and conflicting concurrent tasks without asserting that different modalities never interfere?"]'::jsonb,'PR834 original reviewed head 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7182 v1.4 §4.1.2 — working-memory model; new guide A3 pending','historical A3 43620992688 item PSY-LF05-02: no material findings; revised-guide A3/A4 HOLD'),
('PSY-LF05-07','aqa:aqa-a-level:7182',2,'research-methods','AQA 7182 v1.4 §§4.2.3–4.2.3.2 — experimental design and validity','Design a memory-and-music investigation','A researcher wants to test whether background music affects memory. Forty sixth-form volunteers will learn two different word lists, one in silence and one with music, in counterbalanced order. Design a suitable study and evaluate the main threats to the validity of the findings.','The same 40 volunteers complete both conditions. List difficulty, musical preferences and time of day could affect recall; the research is not yet underway.',16,'["Training classification: Original Revision 16-mark-style research-methods training task, NOT a verified 16-mark tariff for the 2027 AQA research-methods paper.","Research design: Operationalise music versus silence as the independent variable, a scored recall measure as the dependent variable, and an appropriate repeated-measures hypothesis; specify a practical procedure with standardised instructions.","Critical list control: Counterbalance or otherwise equate which word list appears in which condition AND the order of music and silence; merely swapping the order without controlling list difficulty confounds condition with materials.","Applied procedure and ethics: Explain group/order allocation for the 40 volunteers, timing, consistent volume or music conditions, voluntary participation, informed consent and withdrawal, with measures that reduce demand or investigator effects.","Evaluation: Assess order/practice/fatigue effects, list equivalence, musical preference, volunteer sampling, ecological/temporal validity and whether observed recall differences would support a causal inference.","Alternative credit: A fully specified independent-groups comparison may be evaluated as an alternative with its own individual-differences trade-off; do not treat a replacement design as satisfying the supplied repeated-measures brief without explaining the deviation.","Response quality: Strong answers give replicable operational detail, relate each control/weakness to this specific sample and task, and weigh genuine trade-offs. No official examiner mark or numeric AO distribution is inferred.","Self-review prompt: Did I counterbalance order AND list-condition assignment, and explain why each identified threat could change the results?"]'::jsonb,'PR834 original reviewed head 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7182 v1.4 §§4.2.3–4.2.3.2 — experimental design and validity; new guide A3 pending','historical A3 43620992688 item PSY-LF05-07: no material findings; revised-guide A3/A4 HOLD'),
('BUS-LF05-03-16','aqa:aqa-a-level:7132',2,'marketing','AQA 7132 v2.0 §3.3 — market research and marketing decisions','Mira Sports Drinks: product or price?','Evaluate whether Mira Sports Drinks should introduce a sugar-free premium product rather than cut prices on its current range.','Mira Sports Drinks has a 12% market share. Sales volume fell 8% after a £1 price rise. A survey of 80 urban athletes finds strong interest in a sugar-free version, but rivals now promote cheaper alternatives.',16,'["Training classification: Original Revision 16-mark-style contextual Business evaluation; AQA''s exact 2027 item-level AO split is not verified and no official mark is awarded.","Accurate knowledge: Explain relevant segmentation, targeting and positioning alongside product and price elements of the marketing mix and price sensitivity.","Case application: Use Mira''s 12% share, 8% sales-volume fall after a £1 price rise, interest in sugar-free products among 80 urban athletes, and cheaper rival offers. The survey is limited and may not represent the wider market.","Developed analysis: Explain plausible benefits of premium sugar-free differentiation versus reducing prices to defend sales volumes and share; connect customer demand, margins and brand position, using conditional causal reasoning.","Evidence boundaries: The stimulus does not supply contribution per unit, production capacity, launch cost or a reliable price elasticity estimate. Discuss these as unknown decision risks, not established facts or calculable certainties.","Reasoned judgement: Compare both choices and justify a conditional recommendation linked to contribution, representativeness of market testing and competitor response. Credit defensible alternatives on the same evidence.","Response quality: Strong answers use multiple real case facts, reason through competing consequences and support a qualified judgement; a generic list of four Ps or unsupported claims about profitability remains limited.","Self-review prompt: Did I make a genuine choice, treat sample and price-change evidence cautiously, and avoid inventing margin or production-capacity figures?"]'::jsonb,'PR834 original reviewed head 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7132 v2.0 §3.3 — market research and marketing decisions; new guide A3 pending','historical A3 43620992688 item BUS-LF05-03-16: no material findings; revised-guide A3/A4 HOLD'),
('BUS-LF05-04-25','aqa:aqa-a-level:7132',1,'operations','AQA 7132 v2.0 §3.4.3 — lean production and operational efficiency','Lean production versus other competitiveness tools','To what extent is lean production the most effective way for a manufacturer to improve its competitiveness?',NULL,25,'["Training classification: Original Revision 25-mark-style Paper 1 broad essay, not an official or independently examiner-calibrated AQA 2027 marking scheme; no supplied case is compulsory.","Selected knowledge: Explain lean production, waste reduction, just-in-time versus just-in-case inventory, and efficiency/productivity. Capacity utilisation or quality are useful where directly connected to a causal argument rather than listed as unrelated definitions.","Applied examples: Use coherent manufacturer examples (actual or plausible) to distinguish situations with reliable supply, variable demand or tight quality demands. No fictitious case data is provided or required.","Developed analysis: Explain plausible cost, responsiveness, lead-time and quality benefits, alongside lean vulnerabilities such as stockouts, supplier disruption, employee capability and excessive pressure on quality.","Comparison: Evaluate alternatives such as automation, process improvement, quality management or investment in flexible capacity, explaining the conditions in which each beats lean methods.","Balanced judgement: Weigh competitiveness as cost, reliability, quality and differentiation; reach a justified comparative position conditional on supply-chain stability and customer needs.","Response quality: Strong answers sustain connected competing causal chains, specific illustration and a justified overall judgement. Lists of lean slogans or unsupported numerical claims are insufficient.","Self-review prompt: Did I compare lean with genuine alternatives and explain why the best approach depends on the manufacturer''s situation?"]'::jsonb,'PR834 original reviewed head 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7132 v2.0 §3.4.3 — lean production and operational efficiency; new guide A3 pending','historical A3 43620992688 item BUS-LF05-04-25: no material findings; revised-guide A3/A4 HOLD'),
('BUS-LF05-07-25','aqa:aqa-a-level:7132',1,'strategic-position','AQA 7132 v2.0 §3.7 — analysing strategic position and quantitative information','Quantitative versus qualitative strategic analysis','To what extent are quantitative methods more valuable than qualitative assessment when managers analyse a business''s strategic position?',NULL,25,'["Training classification: Original Revision 25-mark-style Paper 1 strategic analysis essay; the precise AQA 2027 item-level tariff and AO marks are not verified.","Selected knowledge: Explain how quantitative ratios, trend forecasts and selected investment-appraisal estimates differ from qualitative information about customers, management, culture and competitive context; distinguish a tool from the evidence it contains.","Relevant context: Illustrate comparisons using reasonable contrasting business situations, without inventing a compulsory supplied case or assuming a named company''s private figures.","Developed analysis: Quantitative evidence can support comparison, measurement and prioritisation but ratios depend on accounts and definitions while forecasts/appraisals rest on uncertain assumptions. Explain which questions the numbers can and cannot answer.","Qualitative balance: Analyse how stakeholder insight, culture, SWOT/PEST-style judgements and strategic capabilities add context. SWOT and external-analysis tools may mix numeric and qualitative evidence; do not misclassify them as inherently quantitative.","Balanced judgement: Compare methods for distinct purposes, industry conditions, scale and uncertainty; a mixed approach may be strongest, but credit a reasoned quantitatively or qualitatively weighted judgement.","Response quality: Strong answers develop competing chains with relevant examples, interrogate evidence limitations and sustain a conditional judgement, not a list of tools or an asserted universal ranking.","Self-review prompt: Did I distinguish measurement from judgement, explain forecast uncertainty and consider genuinely qualitative factors in the specific strategic decision?"]'::jsonb,'PR834 original reviewed head 675fdc8c53a224fe8fa9a81079b57b15dafef7af; AQA 7132 v2.0 §3.7 — analysing strategic position and quantitative information; new guide A3 pending','historical A3 43620992688 item BUS-LF05-07-25: no material findings; revised-guide A3/A4 HOLD');
-- Fail closed on duplicate or unexpected previous catalogue size. Previous six stay untouched.
do $assert$
begin
  if (select count(*) from public.lf05_written_questions)<>6
  or (select count(*) from public.lf05_written_guides)<>6
  or exists(select 1 from public.lf05_written_questions where id in (select id from lf05_next_six))
  then raise exception 'LF-05 next-six staging expects exactly six unchanged earlier records';
  end if;
end
$assert$;
insert into public.lf05_written_questions
(id,course_id,paper_number,topic_id,skill_ref,title,question_prompt,stimulus,marks_style,
 content_fingerprint,original_training_only,status,approved_source_ref)
select id,course_id,paper_number,topic_id,skill_ref,title,question_prompt,stimulus,marks_style,
 encode(sha256(convert_to(id||chr(31)||question_prompt||chr(31)||coalesce(stimulus,'')||chr(31)||guidance::text,'UTF8')),'hex'),
 true,'held',approved_source_ref from lf05_next_six;
insert into public.lf05_written_guides
(question_id,content_fingerprint,guidance,approved_review_ref)
select q.id,q.content_fingerprint,s.guidance,s.approved_review_ref
from lf05_next_six s join public.lf05_written_questions q on q.id=s.id;
-- No new "published" status, user permission, mark, progress or mock question here.
commit;
